/* baby steps service worker (generated by scripts/postbuild-sw.mjs; do not edit out/sw.js). */
/* eslint-disable no-restricted-globals */
const BUILD = '__BUILD__';
const SHELL_CACHE = `bs-shell-${BUILD}`;
const CATALOG_CACHE = 'bs-catalog';
const PRECACHE = __PRECACHE__;
const CATALOG_PRECACHE = __CATALOG_PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const shell = await caches.open(SHELL_CACHE);
      await shell.addAll(PRECACHE);
      const cat = await caches.open(CATALOG_CACHE);
      // Catalog version folders are immutable: only fetch what we don't have.
      for (const url of CATALOG_PRECACHE) {
        if (!(await cat.match(url))) await cat.add(url).catch(() => {});
      }
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith('bs-shell-') && k !== SHELL_CACHE).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

async function networkFirst(request, cacheName, fallbackUrl) {
  const cache = await caches.open(cacheName);
  try {
    const res = await fetch(request, { cache: 'no-store' });
    if (res.ok) cache.put(fallbackUrl || request, res.clone());
    return res;
  } catch (e) {
    const hit = (await cache.match(fallbackUrl || request, { ignoreSearch: true })) || (await caches.match(request, { ignoreSearch: true }));
    if (hit) return hit;
    throw e;
  }
}

async function cacheFirst(request, cacheName, ignoreSearch) {
  const hit = await caches.match(request, { ignoreSearch });
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) (await caches.open(cacheName)).put(request, res.clone());
  return res;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const p = url.pathname;

  // latest.json: always ask the network (never cached by HTTP), fall back to the last copy offline.
  if (p === '/catalog/latest.json') {
    event.respondWith(networkFirst(req, CATALOG_CACHE, '/catalog/latest.json'));
    return;
  }
  // Versioned catalog files are immutable.
  if (p.startsWith('/catalog/v')) {
    event.respondWith(cacheFirst(req, CATALOG_CACHE, false));
    return;
  }
  // Page navigations: network first, then the cached app shell for that route (ignoring ?id=).
  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          return await fetch(req);
        } catch {
          const path = p.endsWith('/') ? p : `${p}/`;
          return (await caches.match(path)) || (await caches.match('/'));
        }
      })(),
    );
    return;
  }
  // Static assets and RSC payloads (index.txt?_rsc=...).
  event.respondWith(cacheFirst(req, SHELL_CACHE, p.endsWith('.txt')));
});
